spec.setup_code:
var T = 14;
function sm(x) { x = Math.max(0, Math.min(1, x)); return x * x * (3 - 2 * x); }
function clamp(x, a, b) { return Math.max(a, Math.min(b, x)); }
function rng(seed) {
  return function () {
    seed = seed | 0; seed = seed + 0x6D2B79F5 | 0;
    var t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
var R = rng(2024);
function gauss() { return Math.sqrt(-2 * Math.log(1 - R())) * Math.cos(2 * Math.PI * R()); }

var F = [[-0.9,0.5],[-0.6,0.8],[-0.2,0.6],[-0.3,0.2],[0.1,0.0],[0.5,0.2],[0.8,-0.1],[0.6,-0.5],[0.2,-0.7],[-0.3,-0.6]];
var N = 10;
var fa = [], wob = [], wa = [], chi1 = [], chi2 = [];
for (var i = 0; i < N; i++) {
  var a = F[Math.max(0, i - 1)], b = F[Math.min(N - 1, i + 1)];
  fa.push(Math.atan2(b[1] - a[1], b[0] - a[0]));
  wob.push([gauss() * 0.35, gauss() * 0.35]);
  wa.push(gauss() * 0.8);
  chi1.push(gauss() * 0.7);
  chi2.push(gauss() * 0.9);
}
// AF3 atoms: 4 per residue = 40
var base = [];
for (var i = 0; i < N; i++) {
  for (var k = 0; k < 4; k++) {
    var ang = k * 1.6 + i;
    base.push([F[i][0] + 0.07 * Math.cos(ang), F[i][1] + 0.07 * Math.sin(ang)]);
  }
}
var seeds = [];
for (var s = 0; s < 3; s++) {
  var sd = { init: [], fin: [], ph: [] };
  var shift = [];
  for (var i = 0; i < N; i++) shift.push([gauss() * 0.06, gauss() * 0.06]);
  for (var j = 0; j < base.length; j++) {
    var ix = clamp(gauss() * 0.5, -1.15, 1.15), iy = clamp(gauss() * 0.5, -1.15, 1.15);
    sd.init.push([ix, iy]);
    var r = j >> 2;
    sd.fin.push([base[j][0] + shift[r][0] + gauss() * 0.02, base[j][1] + shift[r][1] + gauss() * 0.02]);
    sd.ph.push(R() * 6.28);
  }
  seeds.push(sd);
}
var blues = ["#062E75", "#0B4FC0", "#6FA2EC"];

function wrapLines(ctx, text, maxW) {
  var words = text.split(' '), lines = [], cur = '';
  for (var i = 0; i < words.length; i++) {
    var test = cur ? cur + ' ' + words[i] : words[i];
    if (ctx.measureText(test).width > maxW && cur) { lines.push(cur); cur = words[i]; }
    else cur = test;
  }
  if (cur) lines.push(cur);
  return lines;
}

function panelFrame(ctx, P, fs, title, status, cap) {
  ctx.textAlign = 'left';
  ctx.fillStyle = '#04204B';
  ctx.font = 'bold 13px sans-serif';
  ctx.fillText(title, P.x, P.y + 13);
  ctx.fillStyle = '#3D5F91';
  ctx.font = fs + 'px sans-serif';
  ctx.fillText(status, P.x, P.y + 30);
  var lines = wrapLines(ctx, cap, P.w);
  var lh = fs + 3;
  var capTop = P.y + P.h - lines.length * lh;
  for (var i = 0; i < lines.length; i++) ctx.fillText(lines[i], P.x, capTop + (i + 1) * lh - 3);
  var top = P.y + 38, bot = capTop - 4;
  return { cx: P.x + P.w / 2, cy: (top + bot) / 2, hw: P.w / 2, hh: (bot - top) / 2 };
}

function draw(ctx, width, height, time, dt) {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, width, height);
  var t = time % T;
  var alpha = Math.min(sm(t / 0.5), sm((T - t) / 0.6));
  var stacked = width < 620;
  var fs = stacked ? 11 : 12;
  var top = 34, pad = 10, P1, P2;
  if (stacked) {
    var ph = (height - top - 6) / 2;
    P1 = { x: pad, y: top, w: width - 2 * pad, h: ph - 5 };
    P2 = { x: pad, y: top + ph + 3, w: width - 2 * pad, h: ph - 5 };
  } else {
    var pw = width / 2;
    P1 = { x: pad, y: top, w: pw - 1.5 * pad, h: height - top - 8 };
    P2 = { x: pw + 0.5 * pad, y: top, w: pw - 1.5 * pad, h: height - top - 8 };
  }
  // separator
  ctx.strokeStyle = '#8098BC'; ctx.globalAlpha = 0.4; ctx.lineWidth = 1;
  ctx.beginPath();
  if (stacked) { ctx.moveTo(pad, P1.y + P1.h + 2.5); ctx.lineTo(width - pad, P1.y + P1.h + 2.5); }
  else { ctx.moveTo(width / 2, top); ctx.lineTo(width / 2, height - 8); }
  ctx.stroke();
  ctx.globalAlpha = 1;

  // top phase caption
  var phase = t < 1 ? 0 : t < 9 ? 1 : t < 11.5 ? 2 : 3;
  var tops = ['Start: frames collapsed / atoms are pure noise', 'Refining: 8 IPA blocks vs. 50 denoising steps', 'Final: χ side chains vs. three sampled structures', 'One prediction vs. an ensemble of samples'];
  ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center'; ctx.fillStyle = '#04204B';
  ctx.fillText(tops[phase], width / 2, 20);

  var lq = clamp((t - 1) / 8, 0, 1);
  var stage = lq * 8;
  var kk = Math.min(7, Math.floor(stage));
  var prog = lq >= 1 ? 1 : (kk + sm(stage - kk)) / 8;
  var block = lq <= 0 ? 0 : Math.min(8, kk + 1);
  var e = sm(lq);
  var sc = sm((t - 9) / 1.5);
  var bf = sm((t - 8.5) / 1.5);

  ctx.globalAlpha = alpha;
  // ---------- AF2 ----------
  var st2 = block === 0 ? 'init: all frames at the origin' : ('IPA block ' + block + ' / 8') + (sc > 0.5 ? ' + torsions χ' : '');
  var A = panelFrame(ctx, P1, fs, 'AF2: structure module', st2, 'one deterministic prediction, frames + torsions, equivariant attention (IPA)');
  var s = Math.min(A.hw * 0.9, A.hh) / 1.15;
  var pos = [];
  var bump = Math.sin(Math.PI * prog);
  for (var i = 0; i < N; i++) {
    pos.push([A.cx + (F[i][0] * prog + wob[i][0] * bump) * s, A.cy - (F[i][1] * prog + wob[i][1] * bump) * s]);
  }
  ctx.strokeStyle = '#8098BC'; ctx.lineWidth = 1.5; ctx.globalAlpha = alpha * clamp(prog * 2, 0, 1);
  ctx.beginPath();
  for (var i = 0; i < N; i++) { if (i === 0) ctx.moveTo(pos[i][0], pos[i][1]); else ctx.lineTo(pos[i][0], pos[i][1]); }
  ctx.stroke();
  ctx.globalAlpha = alpha;
  // side chains
  if (sc > 0) {
    ctx.strokeStyle = '#B4552F'; ctx.fillStyle = '#B4552F'; ctx.lineWidth = 1.5;
    for (var i = 0; i < N; i++) {
      var ang = -fa[i] + (i % 2 ? 1 : -1) * Math.PI / 2 + chi1[i];
      var L = s * 0.17 * sc;
      var x1 = pos[i][0] + L * Math.cos(ang), y1 = pos[i][1] + L * Math.sin(ang);
      var ang2 = ang + chi2[i];
      var x2 = x1 + L * Math.cos(ang2), y2 = y1 + L * Math.sin(ang2);
      ctx.beginPath(); ctx.moveTo(pos[i][0], pos[i][1]); ctx.lineTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
      ctx.beginPath(); ctx.arc(x2, y2, 1.8, 0, 6.29); ctx.fill();
    }
  }
  // frames (triangles)
  var r = Math.max(4.5, s * 0.09);
  ctx.fillStyle = 'rgba(11,79,192,0.55)'; ctx.strokeStyle = '#04204B'; ctx.lineWidth = 1;
  for (var i = 0; i < N; i++) {
    var a = -(fa[i] * prog + wa[i] * bump);
    var ca = Math.cos(a), sa = Math.sin(a);
    var pts = [[r, 0], [-0.6 * r, 0.65 * r], [-0.6 * r, -0.65 * r]];
    ctx.beginPath();
    for (var m = 0; m < 3; m++) {
      var px = pos[i][0] + pts[m][0] * ca - pts[m][1] * sa;
      var py = pos[i][1] + pts[m][0] * sa + pts[m][1] * ca;
      if (m === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath(); ctx.fill(); ctx.stroke();
  }
  // block progress ticks
  ctx.font = '11px sans-serif'; ctx.textAlign = 'left';
  for (var b = 0; b < 8; b++) {
    ctx.fillStyle = b < block ? '#0B4FC0' : '#8098BC';
    ctx.globalAlpha = alpha * (b < block ? 1 : 0.4);
    ctx.fillRect(P1.x + P1.w - 8 * 9 + b * 9, A.cy - A.hh, 7, 4);
  }
  ctx.globalAlpha = alpha;

  // ---------- AF3 ----------
  var step = Math.round(lq * 50);
  var sigma = 1.6 * Math.pow(1 - e, 1.5) + 0.02;
  var st3 = 'denoising step ' + step + ' / 50  ·  noise σ = ' + sigma.toFixed(2);
  var B = panelFrame(ctx, P2, fs, 'AF3: diffusion module', st3, 'all atoms directly, a generative model: different noise → different samples; no frames, no torsions, no equivariance');
  var s3 = Math.min(B.hw * 0.9, B.hh) / 1.15;
  var k1 = Math.pow(1 - e, 1.4);
  for (var q = 0; q < 3; q++) {
    var sd = seeds[q];
    var P = [];
    for (var j = 0; j < sd.fin.length; j++) {
      var w = 0.07 * (1 - e) * Math.sin(time * 5 + sd.ph[j]);
      var x = sd.fin[j][0] + (sd.init[j][0] - sd.fin[j][0]) * k1 + w;
      var y = sd.fin[j][1] + (sd.init[j][1] - sd.fin[j][1]) * k1 + w * 0.8;
      P.push([B.cx + x * s3, B.cy - y * s3]);
    }
    if (bf > 0) {
      ctx.strokeStyle = blues[q]; ctx.lineWidth = 1.2; ctx.globalAlpha = alpha * bf * 0.6;
      ctx.beginPath();
      for (var j = 0; j < P.length; j++) { if (j === 0) ctx.moveTo(P[j][0], P[j][1]); else ctx.lineTo(P[j][0], P[j][1]); }
      ctx.stroke();
    }
    ctx.fillStyle = blues[q]; ctx.globalAlpha = alpha * 0.75;
    for (var j = 0; j < P.length; j++) {
      ctx.beginPath(); ctx.arc(P[j][0], P[j][1], 2.4, 0, 6.29); ctx.fill();
    }
  }
  ctx.globalAlpha = alpha;
  // legend
  ctx.font = '11px sans-serif'; ctx.textAlign = 'left';
  var lx = P2.x + P2.w - 50, ly = B.cy - B.hh + 6;
  for (var q = 0; q < 3; q++) {
    ctx.fillStyle = blues[q];
    ctx.beginPath(); ctx.arc(lx, ly + q * 13, 3.5, 0, 6.29); ctx.fill();
    ctx.fillStyle = '#3D5F91';
    ctx.fillText('seed ' + (q + 1), lx + 8, ly + q * 13 + 4);
  }
  ctx.globalAlpha = 1;
}
return { draw: draw };
